/* Animations */
@keyframes slideInFromLeft {
  from {
    opacity: 0;
    transform: translateX(-50px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInFromRight {
  from {
    opacity: 0;
    transform: translateX(50px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes fadeIn {
  from {
    opacity: 0;
  }

  to {
    opacity: 1;
  }
}

@keyframes slideDownFromTop {
  from {
    opacity: 0;
    transform: translateY(-100px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideUpFromBottom {
  from {
    opacity: 0;
    transform: translateY(100px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

:root {
  --blue: #0e86c9;
  --blue-2: #1ca0e3;
  --blue-deep: #0b5e96;
  --btn: #1274b8;
  --navy: #0a2a4a;
  --navy-2: #0e3a63;
  --ink: #16273f;
  --body: #5c6b80;
  --white: #fff;
  --soft: #f4f6f8;
  --line: #e7edf3;
  --star: #f5901f;
  --grad-navy: linear-gradient(120deg, #082138 0%, #0c4674 55%, #0e5f96 100%);
  --shadow-sm: 0 2px 12px rgba(16, 39, 63, 0.06);
  --shadow-md: 0 16px 40px rgba(16, 39, 63, 0.1);
  --shadow-lg: 0 30px 70px rgba(16, 39, 63, 0.16);
  --r: 16px;
  --maxw: 1360px;
  --pad: clamp(20px, 5vw, 120px);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
  overflow-x: hidden;
}

body {
  margin: 0;
  font-family: "Poppins", sans-serif;
  color: var(--ink);
  background: #fff;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  font-weight: 400;
  font-size: 16px;
}

h1,
h2,
h3,
h4 {
  font-family: "Poppins", sans-serif;
  margin: 0;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: var(--ink);
  font-weight: 600;
}

p {
  margin: 0;
}
h2 > span,
h1 > span {
  color: #046daa;
}
h1 {
  color: #fff;
  font-size: clamp(32px, 4.4vw, 50px);
}
h2 {
  font-size: clamp(28px, 4.5vw, 44px);
}

img {
  display: block;
  max-width: 100%;
  height: auto;
}

a {
  color: inherit;
  text-decoration: none;
}

.wrap {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--pad);
}

.blue {
  color: var(--blue);
}

.eyebrow {
  font-family: "Poppins", sans-serif;
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: #185686;
  margin-bottom: 16px;
  display: inline-block;
}
.home  p{
    font-size: clamp(14px, 1.4vw, 16px);
      font-family: "Poppins", sans-serif;
        font-weight: 500;
  color: #626262;

}
.lead {
  font-size: clamp(14px, 1.4vw, 16px);
  font-family: "Poppins", sans-serif;
  max-width: 700px;
  margin-top: 30px;
  font-weight: 500;
  color: #626262;
}

.sub {
  font-family: "Inter", sans-serif;
  font-size: 16px;
  font-weight: 400;
  line-height: 1.6;
  color: rgba(255, 255, 255, 0.8);
  margin: 20px 0;
}

/* reveal */
.reveal {
  transform: translateY(28px);
  transition:
    opacity 0.7s cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}

.reveal.in {
  opacity: 1;
  transform: none;
}

.reveal[data-d="1"] {
  transition-delay: 0.08s;
}

.reveal[data-d="2"] {
  transition-delay: 0.16s;
}

.reveal[data-d="3"] {
  transition-delay: 0.24s;
}

.reveal[data-d="4"] {
  transition-delay: 0.32s;
}

/* buttons */
.btn {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: "Poppins", sans-serif;
  font-weight: 600;
  font-size: 14px;
  letter-spacing: 2%;
  text-transform: uppercase;
  padding: 12px 28px;
  border-radius: 90px;
  cursor: pointer;
  border: 1px solid transparent;
  overflow: hidden;
  transition:
    transform 0.3s ease,
    box-shadow 0.3s ease,
    background 0.3s ease,
    border-color 0.3s ease;
  text-decoration: none;
}

.btn .circle {
  width: 30px;
  height: 30px;
  border-radius: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  transition: transform 0.3s ease;
}

/* Primary Button */
.btn.primary {
  background: #ffffff;
  color: #005386;
  border-color: #005386;
  box-shadow: 0 4px 16px rgba(28, 160, 227, 0.3);
}

.btn.primary .circle {
  background: #0093cf;
}

.btn.primary .circle svg path {
  stroke: #fff;
}

.btn.primary:hover {
  background: #1588c7;
  border-color: #1588c7;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(28, 160, 227, 0.4);
}

.btn.primary:hover .circle {
  background: rgba(255, 255, 255, 0.3);
  transform: translateX(3px);
}

/* Ghost Button */
.btn.ghost {
  background: transparent;
  color: #fff;
  border-color: rgba(255, 255, 255, 0.4);
}

.btn.ghost .circle {
  background: #0093cf;
}

.btn.ghost .circle svg path {
  stroke: #fff;
}

.btn.ghost:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(255, 255, 255, 0.2);
}

.btn.ghost:hover .circle {
  background: rgba(255, 255, 255, 0.2);
  transform: translateX(3px);
}

.btn.light {
  background: #fff;
  color: var(--btn);
}

.btn.light:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.btn.line-dark {
  background: transparent;
  color: #fff;
  border-color: rgba(255, 255, 255, 0.4);
}

.btn.line-dark:hover {
  background: #fff;
  color: var(--btn);
  transform: translateY(-2px);
}

.btn.line-dark:hover .circle svg path {
  stroke: var(--btn);
}

/* ===== Legacy Support — shared spacing utility =====
   .pad — vertical spacing utility applied directly on <section>
   elements, e.g. Industries (section.pad#industries) and
   FAQ (.faq-section.pad#faq).
   .sec-head — shared section-header spacing wrapper. */
section.pad {
  padding: clamp(60px, 7vw, 104px) 0;
}

.sec-head {
  margin-bottom: 44px;
}

/* ===== Header — <header id="hdr"> ===== */
header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  transition:
    background 0.3s,
    box-shadow 0.3s,
    padding 0.3s;
  padding: 14px 0;
}

header.scrolled {
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(10px);
  box-shadow: 0 6px 24px rgba(16, 39, 63, 0.07);
  padding: 8px 0;
}

header .nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

header .logo {
  display: flex;
  align-items: center;
  gap: 9px;
  font-family: "Poppins", sans-serif;
  font-weight: 700;
  font-size: 22px;
  color: #fff;
  transition: color 0.3s;
}

header.scrolled .logo {
  color: var(--ink);
}

header .logo .mark {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: conic-gradient(from 210deg, var(--blue-2), var(--blue-deep));
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 12px rgba(14, 134, 201, 0.4);
}

header .logo small {
  font-family: "Inter", sans-serif;
  font-weight: 400;
  font-size: 8px;
  letter-spacing: 0.18em;
  display: block;
  opacity: 0.7;
  margin-top: -3px;
}

header .menu {
  display: flex;
  align-items: center;
  gap: 28px;
  font-family: "Poppins", sans-serif;
  font-weight: 500;
  font-size: 14px;
  color: rgba(255, 255, 255, 0.9);
}

header.scrolled .menu {
  color: var(--ink);
}

header .menu a {
  position: relative;
  padding: 4px 0;
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

header .menu a::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: -2px;
  height: 2px;
  width: 0;
  background: var(--blue-2);
  transition: width 0.3s;
}

header .menu a:hover::after {
  width: 100%;
}

header .menu a:hover {
  color: var(--blue-2);
}

header .burger {
  display: none;
  flex-direction: column;
  gap: 5px;
  cursor: pointer;
  padding: 8px;
}

header .burger span {
  width: 24px;
  height: 2px;
  background: #fff;
  transition: 0.3s;
}

header.scrolled .burger span {
  background: var(--ink);
}

/* ===== Logo Strip — .logostrip =====
   Reused for three sections in Home.html: Trusted Clients (id="clients"),
   We Are Partners With (.logostrip.on-dark id="partners"), and
   Featured In (.logostrip.on-dark). */
.logostrip {
  padding: 55px 0;
  border-bottom: 1px solid #ececec;
  background: #ffffff;
  position: relative;
}

.logostrip.on-dark {
  position: relative;
  background: var(--grad-navy);
  color: #fff;
  overflow: hidden;
  z-index: 1;
}

