.logostrip .logostrip-content {
  display: flex;
  align-items: center;
  gap: 48px;
}

.logostrip .logostrip-label {
  flex: 0 0 auto;
  min-width: 170px;
  padding-top: 6px;
}

#clients .logostrip-label{
  border-right: 1px solid var(--body)
}

.logostrip .trusted-label {
  font-family: "Poppins", sans-serif;
  font-weight: 600;
  font-size: 20px;
  color: #555;
  line-height: 1.5;
  margin: 0;
  letter-spacing: 0.3px;
  max-width: 142px;
}

.logostrip .clients-slider {
  flex: 1;
  position: relative;
}

.logostrip .client-logo-item {
  display: flex !important;
  align-items: center;
  justify-content: center;
  padding: 0 32px;
  min-height: 80px;
}

.logostrip .client-logo {
  max-width: 100%;
  width: 100%;
  max-height: 50px;
  height: auto;
  object-fit: contain;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  filter: grayscale(100%);
  display: block;
}

.logostrip svg.client-logo {
  max-width: 120px;
  width: 100%;
  height: auto;
}

.logostrip .client-logo:hover {
  filter: grayscale(0%);
  opacity: 1;
  transform: scale(1.08);
}

/* Slick Slider for Clients */
.logostrip .slick-track {
  display: flex;
  align-items: center;
}

.logostrip .slick-slide {
  display: flex;
  align-items: center;
  justify-content: center;
  height: auto;
}

.logostrip .slick-list {
  margin: 0;
}

.logostrip .slick-dots {
  display: none;
}

.logostrip .head {
  position: relative;
  margin-bottom: 76px;
}

.logostrip .head h2 {
  color: #fff;
  text-align: center;
}

#partners.logostrip .head h2 {
  text-align: start;
}

.logostrip .marquee {
  overflow: hidden;
  flex: 1;
  -webkit-mask-image: linear-gradient(
    90deg,
    transparent,
    #000 8%,
    #000 92%,
    transparent
  );
  mask-image: linear-gradient(
    90deg,
    transparent,
    #000 8%,
    #000 92%,
    transparent
  );
}

.logostrip .mtrack {
  display: flex;
  align-items: center;
  width: max-content;
  animation: scrollx 32s linear infinite;
  gap: 30px;
}

.logostrip .mtrack img {
  height: 85px;
  width: auto;
  object-fit: contain;
  flex-shrink: 0;
  background-color: #fff;
  gap: 7.76px;
  border-radius: 12.41px;
  padding: 14px;
}


.logostrip .marquee:hover .mtrack {
  animation-play-state: paused;
}

@keyframes scrollx {
  to {
    transform: translateX(-50%);
  }
}

.logostrip .trusted-label {
  font-family: "Poppins", sans-serif;
  font-weight: 600;
  font-size: 20px;
  color: var(--body);
  line-height: 1.5;
  margin: 0;
}


.sidebar-menu {
  display: none;
}
/* ===== Responsive Overrides — header, logostrip, footer ===== */
@media (max-width: 1024px) {
  .footer .footer__cols {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 680px) {
  header .menu {
    display: none;
  }

  header .burger {
    display: flex;
  }

  .footer .footer__cols {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.001s;
    transition-duration: 0.001s;
  }


}

@media (max-width: 768px) {
  .eyebrow {
        font-size: 12px;
        margin-bottom: 16px;
    }
  .logostrip .trusted-label {
      max-width: 100%;
    }

    #clients .logostrip-label {
      border: none;
    }

    .logostrip .logostrip-content {
      flex-direction: column;
    }
}
